killed = 0
for name, mod, old, new, check in KNOCKS:
    src = open(os.path.join(MOD, mod), encoding='utf-8').read()
    n = src.count(old)
    if n != 1: print(f'  BAD  {name}: expected 1 match in {mod}, found {n}'); continue
    tmp = tempfile.mkdtemp(prefix='mkg2-knock-')
    try:
        for f in os.listdir(MOD): shutil.copy(os.path.join(MOD, f), tmp)
        open(os.path.join(tmp, mod), 'w', encoding='utf-8', newline='\n').write(src.replace(old, new))
        p = subprocess.run(['node', TEST], capture_output=True, text=True, encoding='utf-8', env=dict(os.environ, MKG2_MODULES=tmp))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    crashed = 'v2 unit checks' not in p.stdout
    hit = any(l.startswith('FAIL ' + check) for l in p.stdout.splitlines())
    ok = hit and not crashed
    killed += ok
    print(f'  {"KILLED" if ok else "CRASHED" if crashed else "SURVIVED"}  {name}  ->  {check.strip()}')
print(f'{killed} of {len(KNOCKS)} killed')
sys.exit(0 if killed == len(KNOCKS) else 1)
